        self.config = config
        self.data_store = {}

    def store_item(self, key, item):
        if not isinstance(item, dict) or 'id' not in item.keys():
            raise ValueError("Item must be a dictionary with an 'id'")
        if item['id'] in self.data_store:
            raise ValueError(f"Duplicate ID: {item['id']}")

        # Example implementation using flat file (for simplicity):
        f = open(self.config.storage_path, 'a')
        f.write(f"{json.dumps(item)}\n")
        f.close()

    def retrieve_item(self, key):
        if not isinstance(key, str) or len(key.strip()) == 0:
            raise ValueError("Key must be a nonempty string")

        item = None
        try:
            with open(self.config.storage_path, 'r') as f:
                for line in f:
                    data = json.loads(line)
                    if data['id'] == key:
                        item = data
                        break

            if not item:
                raise KeyError(f"Item {key} not found")
        except FileNotFoundError:
            raise FileNotFoundError("Storage file not found")

        return item

    def delete_item(self, key):
        if not isinstance(key, str) or len(key.strip()) == 0:
            raise ValueError("Key must be a nonempty string")

        try:
            with open(self.config.storage_path, 'r') as f:
                lines = f.readlines()

            with open(self.config.storage_path, 'w') as f:
                for line in lines:
                    data = json.loads(line)
                    if data['id'] != key:
                        f.write(line)

            # Remove the trailing newline
            if lines and lines[-1].strip() == '':
                lines.pop()
            f.writelines(lines)
        except FileNotFoundError:
            raise FileNotFoundError("Storage file not found")
