  tasks: { id: number; title: string; completed: boolean }[];
  addTask(title: string): void;
  toggleTask(id: number): void;
  removeTask(id: number): void;
  saveTasks(): void;
  loadTasks(): void;
}

export interface Command {
  name: string;
  description: string;
  handler: (args: { taskStore: TaskStore }) => void;
}

export const commands: Record<string, Command> = {};

export function addCommand(name: string, description: string, handler: (args: { taskStore: TaskStore }) => void): boolean {
  if (commands[name] !== undefined) return false;
  commands[name] = { name, description, handler };
  return true;
}

export function runCommand(name: string, args: { taskStore: TaskStore }): void {
  const command = commands[name];
  if (!command) throw new Error(`Unknown command: ${name}`);
  try {
    command.handler(args);
  } catch (err) {
    console.error(`Failed to run command ${name}:`, err);
  }
}

export function render(container: HTMLElement) {
  container.innerHTML = `
    <div class="row">
      <div class="col">
        <h1>TodoMate</h1>
        <input id="titleInput" type="text" placeholder="Enter task" />
        <button id="addBtn" class="btn" onclick="addTask()">Add Task</button>
        <div id="tasksList" class="grid"></div>
        <button id="clearBtn" class="btn" onclick="clearCompleted()">Clear Completed</button>
        <button id="darkBtn" class="btn" onclick="toggleDarkMode()">Toggle Dark Mode</button>
      </div>
    </div>
  `;

  const titleInput = document.getElementById('titleInput') as HTMLInputElement;
  const addBtn = document.getElementById('addBtn') as HTMLButtonElement;
  const tasksList = document.getElementById('tasksList') as HTMLDivElement;
  const clearBtn = document.getElementById('clearBtn') as HTMLButtonElement;
  const darkBtn = document.getElementById('darkBtn') as HTMLButtonElement;

  const tasks: { id: number; title: string; done: boolean }[] = [];

  function addTask() {
    if (!titleInput.value.trim()) return;
    tasks.push({ id: tasks.length + 1, title: titleInput.value, done: false });
    updateList();
    titleInput.value = '';
  }

  function updateList() {
    tasksList.innerHTML = '';
    tasks.forEach((task, index) => {
      const card = document.createElement('div');
      card.className = 'card';
      card.style.backgroundColor = '#15152a';
      card.style.border = '1px solid rgba(255,255,255,0.1)';
      card.style.borderRadius = '12px';
      card.style.padding = '16px';
      card.style.minWidth = '220px';

      const title = document.createElement('h3');
      title.textContent = task.title;
      card.appendChild(title);

      const toggle = document.createElement('button');
      toggle.className = 'btn';
      toggle.textContent = task.done ? 'Undo' : 'Done';
      toggle.onclick = () => toggleTask(index);
      card.appendChild(toggle);

      const deleteBtn = document.createElement('button');
      deleteBtn.className = 'btn btn-danger';
      deleteBtn.textContent = 'Delete';
      deleteBtn.onclick = () => deleteTask(index);
      card.appendChild(deleteBtn);

      tasksList.appendChild(card);
    });
  }

  function toggleTask(index: number) {
    tasks[index].done = !tasks[index].done;
    updateList();
  }

  function deleteTask(index: number) {
    tasks.splice(index, 1);
    updateList();
  }

  function clearCompleted() {
    tasks = tasks.filter((task) => !task.done);
    updateList();
  }

  function toggleDarkMode() {
    document.body.classList.toggle('dark');
  }

  addBtn.onclick = addTask;
  clearBtn.onclick = clearCompleted;
  darkBtn.onclick = toggleDarkMode;

  updateList();
}

