export function listTasks(taskStore: TaskStore): Task[] {
  try {
    return taskStore.tasks.map((task) => ({
      id: task.id,
      title: task.title,
      completed: task.completed,
    }));
  } catch (error) {
    console.error('Error retrieving tasks:', error);
    throw new Error('Failed to retrieve tasks');
  }
}

export async function completeTask(taskId: number, taskStore: TaskStore): Promise<void> {
  try {
    taskStore.tasks = taskStore.tasks.map((task) => {
      if (task.id === taskId) {
        return { ...task, completed: !task.completed };
      }
      return task;
    });
  } catch (error) {
    console.error('Error completing task:', error);
    throw new Error('Failed to complete task');
  }
}

export async function deleteTask(taskId: number, taskStore: TaskStore): Promise<void> {
  try {
    taskStore.tasks = taskStore.tasks.filter((task) => task.id !== taskId);
  } catch (error) {
    console.error('Error deleting task:', error);
    throw new Error('Failed to delete task');
  }
}

