export class TaskStore {
  tasks: { title: string; completed: boolean }[] = [];
  title: string = 'Todo List';
  completed: boolean[] = [];
  addTask(title: string) {
    this.tasks.push({ title, completed: false });
    this.completed.push(false);
  }
  toggleTask(index: number) {
    this.completed[index] = !this.completed[index];
  }
  removeTask(index: number) {
    this.tasks.splice(index, 1);
    this.completed.splice(index, 1);
  }
  saveTasks() {
    localStorage.setItem('tasks', JSON.stringify(this.tasks));
  }
  loadTasks() {
    const savedTasks = localStorage.getItem('tasks');
    if (savedTasks) {
      this.tasks = JSON.parse(savedTasks);
      this.completed = Array(this.tasks.length).fill(false);
    }
  }
}

export function parseArgs(argv: string[]): { command: string; subcommand?: string; args: string[] } {
  const args = argv.slice(1);
  const command = args.length > 0 ? args[0] : null;
  const subcommand = args.length > 1 ? args[1] : null;
  return { command, subcommand, args: args.slice(2) };
}

export function loadConfig(): { title: string; theme: 'light' | 'dark' } {
  return { title: 'Todo List', theme: 'light' };
}

export function registerHandlers(handlers: { [key: string]: (taskStore: TaskStore, command: Command, args: string[]) => void }) {
  const commandHandlers = handlers.commands;
  for (const name in commandHandlers) {
    addCommand(name, commandHandlers[name]);
  }
}

export async function startCLILoop() {
  let taskStore = new TaskStore();
  let running = true;
  while (running) {
    const { command, subcommand, args } = parseArgs(process.argv);
    if (command === null) continue;
    let handler = commands[command];
    if (subcommand !== undefined) handler = commands[subcommand];
    if (handler === undefined) continue;
    try {
      await handler(taskStore, { name: command, description: '', handler }, args);
    } catch (error) {
      console.error('An error occurred:', error.message);
    }
  }
}

export async function main() {
  try {
    const config = loadConfig();
    registerHandlers(handlers);
    await startCLILoop();
  } catch (error) {
    console.error('An error occurred:', error.message);
  }
}

export function listTasks(taskStore: TaskStore, command: Command, args: string[]) {
  taskStore.tasks.forEach((task, index) => {
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = task.completed;
    checkbox.addEventListener('change', () => {
      taskStore.toggleTask(index);
    });
    const label = document.createElement('label');
    label.textContent = task.title;
    label.appendChild(checkbox);
    document.body.appendChild(label);
  });
}

