export class TicTacToeGame {
  private board: string[] = ['', '', '', '', '', '', '', '', ''];
  private currentPlayer: 'X' | 'O' = 'X';
  private winner: 'X' | 'O' | null = null;

  constructor() {}

  getCurrentPlayer(): 'X' | 'O' {
    return this.currentPlayer;
  }

  makeMove(pos: number): void {
    if (this.board[pos] === '') {
      this.board[pos] = this.currentPlayer;
      this.currentPlayer = this.currentPlayer === 'X' ? 'O' : 'X';
      this.checkForWinner();
    }
  }

  getBoard(): string[] {
    return this.board;
  }

  getWinner(): 'X' | 'O' | null {
    return this.winner;
  }

  private checkForWinner(): void {
    const winningCombinations = [
      [0, 1, 2],
      [3, 4, 5],
      [6, 7, 8],
      [0, 3, 6],
      [1, 4, 7],
      [2, 5, 8],
      [0, 4, 8],
      [2, 4, 6],
    ];

    for (const [a, b, c] of winningCombinations) {
      if (this.board[a] !== '' && this.board[a] === this.board[b] && this.board[a] === this.board[c]) {
        this.winner = this.board[a];
        return;
      }
    }

    if (this.board.every((cell) => cell !== '')) {
      this.winner = 'DRAW';
    }
  }
}

export function startGame(): void {
  const game = new TicTacToeGame();
  const boardElement = document.createElement('div');
  boardElement.className = 'tictactoe-board';
  for (let i = 0; i < 9; i++) {
    const cell = document.createElement('div');
    cell.className = 'tictactoe-cell';
    cell.textContent = game.getBoard()[i];
    cell.addEventListener('click', () => {
      game.makeMove(i);
      cell.textContent = game.getBoard()[i];
      if (game.getWinner()) {
        document.body.innerHTML = `<h1>Winner: ${game.getWinner()}</h1>`;
      }
    });
    boardElement.appendChild(cell);
  }
  document.body.appendChild(boardElement);
}

