// Define types for Player, BoardState, GameState, and Move

export enum Player {
  X = 'X',
  O = 'O'
}

export interface BoardState {
  cells: Player[];
}

export enum GameState {
  PENDING,
  X_WIN,
  O_WIN,
  DRAW
}

export interface Move {
  row: number;
  col: number;
  player: Player;
}

import { Player, BoardState, GameState, Move } from '../types/types.ts';

export interface Player { symbol: 'X' | 'O'; }
export interface BoardState { cells: (null | Player)[][]; }
export enum GameState { IN_PROGRESS, X_WON, O_WON, DRAW }
export interface Move { row: number; col: number; player: Player; }

export function newBoard(): BoardState {
  return { cells: Array.from({ length: 3 }, () => Array(3).fill(null)) };
}

export function applyMove(row: number, col: number, player: Player): void {
  if (row < 0 || row > 2 || col < 0 || col > 2) return;
  if (null !== board.cells[row][col]) return;
  board.cells[row][col] = player;
}

export function getGameState(): GameState {
  for (let row = 0; row < 3; row++) {
    for (let col = 0; col < 3; col++) {
      if (null === board.cells[row][col]) continue;
      const player = board.cells[row][col];
      if (isWinner(player)) return player.symbol === 'X' ? GameState.X_WON : GameState.O_WON;
    }
  }
  return isDraw() ? GameState.DRAW : GameState.IN_PROGRESS;
}

export function isWinner(player: Player): boolean {
  const winningSequences = [
    [[0, 0], [1, 1], [2, 2]],
    [[0, 2], [1, 1], [2, 0]],
    [[0, 0], [0, 1], [0, 2]],
    [[1, 0], [1, 1], [1, 2]],
    [[2, 0], [2, 1], [2, 2]],
    [[0, 0], [1, 0], [2, 0]],
    [[0, 1], [1, 1], [2, 1]],
    [[0, 2], [1, 2], [2, 2]],
  ];

  for (const sequence of winningSequences) {
    if (sequence.every(([r, c]) => board.cells[r][c] === player)) return true;
  }

  return false;
}

export function isDraw(): boolean {
  for (let row = 0; row < 3; row++) {
    for (let col = 0; col < 3; col++) {
      if (null === board.cells[row][col]) return false;
    }
  }
  return true;
}

