      if (position !== null) {
        const cell = game.board.cells[position];
        if (!cell.player) {
          cell.player = game.currentPlayer;
          if (isWinningMove(game.currentPlayer, position)) {
            alert(`${game.currentPlayer.name} wins!`);
            resetBoard();
          } else {
            changePlayer();
          }
        }
      } else {
        resetBoard();
      }
    }

    function isWinningMove(player: Player, position: number): boolean {
      const [row, col] = getPlayerPosition(position);
      return (
        row === col && row === 0 && game.board.cells.every((cell) => cell.row === row && cell.col === col)
        ||
        row === 1 && [0, 2].includes(col) && game.board.cells.every((cell) => cell.row === row && cell.col === col)
        ||
        col === 2 && row === 0 && game.board.cells.every((cell) => cell.row === row && cell.col === col)
      );
    }

    function getPlayerPosition(cell: Cell): [number, number] {
      return [cell.row, cell.col];
    }

    function changePlayer(): void {
      const currentIndex = game.players.findIndex((player) => player.name === game.currentPlayer.name);
      game.currentPlayer = game.players[currentIndex === game.players.length - 1 ? 0 : currentIndex + 1];
    }

    function resetBoard(): void {
      game.currentPlayer = { name: 'Player X', symbol: 'X' };
      game.board.cells.forEach((cell) => cell.player = null);
    }
  } catch (error) {
    console.error('Failed to mount renderer:', error);
  }
}

import { Player, BoardState, GameState, Move } from '../types/types.ts';

export class MiniMaxAI {
  private static readonly boardSize = 3;

  private static getAvailableMoves(board: BoardState): Move[] {
    return board.cells.flatMap((row, rowIndex) => row.map((cell, colIndex) => ({ row: rowIndex, col: colIndex })).filter((m) => board.cells[m.row][m.col] === null));
  }

  private static minimax(board: BoardState, depth: number, isMaximizing: boolean, alpha: number, beta: number): number {
    const winner = this.getWinner(board);
    if (winner !== null) return winner === Player.X ? 1 : winner === Player.O ? -1 : 0;
    if (this.isBoardFull(board)) return 0;

    if (isMaximizing) {
      let bestScore = -Infinity;
      for (const move of this.getAvailableMoves(board)) {
        const newBoard = this.cloneBoard(board);
        newBoard.cells[move.row][move.col] = Player.X;
        const score = this.minimax(newBoard, depth + 1, false, alpha, beta);
        bestScore = Math.max(score, bestScore);
        alpha = Math.max(alpha, score);
        if (beta <= alpha) break;
      }
      return bestScore;
    } else {
      let bestScore = Infinity;
      for (const move of this.getAvailableMoves(board)) {
        const newBoard = this.cloneBoard(board);
        newBoard.cells[move.row][move.col] = Player.O;
        const score = this.minimax(newBoard, depth + 1, true, alpha, beta);
        bestScore = Math.min(score, bestScore);
        beta = Math.min(beta, score);
        if (beta <= alpha) break;
      }
      return bestScore;
    }
  }

  private static cloneBoard(board: BoardState): BoardState {
    return board.cells.map((row) => [...row]);
  }

  private static getWinner(board: BoardState): Player | null {
    const lines = [
      [0, 1, 2],
      [3, 4, 5],
      [6, 7, 8],
      [0, 3, 6],
      [1, 4, 7],
      [2, 5, 8],
      [0, 4, 8],
      [2, 4, 6],
    ];
    for (const [a, b, c] of lines) {
      if (board.cells[a] !== null && board.cells[a] === board.cells[b] && board.cells[a] === board.cells[c]) return board.cells[a];
    }
    return null;
  }

  private static isBoardFull(board: BoardState): boolean {
    return !board.cells.find((row) => row.some((cell) => cell === null));
  }

  private static getBestMove(board: BoardState): Move {
    let bestMove: Move | null = null;
    let bestScore = -Infinity;
    for (const move of this.getAvailableMoves(board)) {
      const newBoard = this.cloneBoard(board);
      newBoard.cells[move.row][move.col] = Player.X;
      const score = this.minimax(newBoard, 0, false, -Infinity, Infinity);
      if (score > bestScore) {
        bestScore = score;
        bestMove = move;
      }
    }
    return bestMove!;
  }

  makeMove(board: BoardState): Move {
    const move = this.getBestMove(board);
    return { move, score: this.minimax(board, 0, true, -Infinity, Infinity) };
  }

  evaluateState(board: BoardState): number {
    const winner = this.getWinner(board);
    if (winner !== null) return winner === Player.X ? 1 : winner === Player.O ? -1 : 0;
    return 0;
  }
}

import { Player, BoardState, GameState, Move } from '../types/types.ts';

export interface Player { name: string; symbol: 'X' | 'O'; }
export interface BoardState { cells: Array<Array<{ player?: 'X' | 'O'; }>>; }
export interface GameState { cells: BoardState['cells']; player1: Player; player2: Player; lastMove?: { row: number; col: number; player: 'X' | 'O'; }; winner?: 'X' | 'O'; }
export interface Move { row: number; col: number; player: 'X' | 'O'; }

export function newGameState(): GameState {
  return { cells: Array.from({ length: 3 }, () => Array(3).fill({})), player1: { name: 'Player 1', symbol: 'X' }, player2: { name: 'Player 2', symbol: 'O' }, };
}

export function applyMove(row: number, col: number, player: 'X' | 'O', state: GameState): boolean {
  if (state.cells[row][col].player) return false;
  state.cells[row][col].player = player;
  state.lastMove = { row, col, player };
  const winner = calculateWinner(state);
  if (winner) return true;
  const opponent = player === 'X' ? 'O' : 'X';
  const bestMove = findBestMove(state, opponent);
  applyMove(bestMove.row, bestMove.col, opponent, state);
  return true;
}

export function getGameState(): GameState { return {}; }
export function isGameOver(state: GameState): boolean { return false; }
export function getWinner(state: GameState): 'X' | 'O' { return null; }

const WINNING_LINES = [[0, 0], [0, 1], [0, 2], [1, 0], [1, 1], [1, 2], [2, 0], [2, 1], [2, 2]];

function calculateWinner(state: GameState): 'X' | 'O' | null {
  for (const [r1, c1, r2, c2, r3, c3] of WINNING_LINES) {
    const p1 = state.cells[r1][c1].player;
    const p2 = state.cells[r2][c2].player;
    const p3 = state.cells[r3][c3].player;
    if (p1 && p1 === p2 && p2 === p3) return p1;
  }
  return null;
}

function findBestMove(state: GameState, player: 'X' | 'O'): Move {
  let bestScore = -Infinity;
  let bestMove: Move | null = null;
  for (let row = 0; row < 3; row++) {
    for (let col = 0; col < 3; col++) {
      if (state.cells[row][col].player) continue;
      const move: Move = { row, col, player };
      const score = minimax(state, player, move);
      if (score > bestScore) {
        bestScore = score;
        bestMove = move;
      }
    }
  }
  return bestMove!;
}

function minimax(state: GameState, player: 'X' | 'O', move: Move): number {
  const winner = calculateWinner(state);
  if (winner) return player === 'X' ? 1 : -1;
  let score = 0;
  for (let row = 0; row < 3; row++) {
    for (let col = 0; col < 3; col++) {
      if (state.cells[row][col].player) continue;
      const newMove: Move = { row, col, player };
      const newScore = minimax(state, player === 'X' ? 'O' : 'X', newMove);
      score = Math.max(score, newScore);
    }
  }
  return score;
}

