export class TicTacToeUI {
  private gameBoard: string[][] = [[' ', ' ', ' '], [' ', ' ', ' '], [' ', ' ', ' ']];
  private currentPlayer: 'X' | 'O';
  private moves: { row: number; col: number; player: 'X' | 'O' }[] = [];

  constructor() {
    this.currentPlayer = 'X';
  }

  public startGame(): void {
    this.gameBoard = [[' ', ' ', ' '], [' ', ' ', ' '], [' ', ' ', ' ']];
    this.currentPlayer = 'X';
    this.moves = [];
  }

  public handleUserMove(row: number, col: number): void {
    if (row < 0 || row > 2 || col < 0 || col > 2) {
      throw new Error('Invalid move!');
    }
    if (this.gameBoard[row][col] !== ' ') {
      throw new Error('Cell already occupied!');
    }

    this.gameBoard[row][col] = this.currentPlayer;
    this.moves.push({ row, col, player: this.currentPlayer });
    this.nextPlayer();
    this.checkForWinner();
  }

  private nextPlayer(): void {
    this.currentPlayer = this.currentPlayer === 'X' ? 'O' : 'X';
  }

  private checkForWinner(): void {
    const winningCombinations = [
      [[0, 0], [0, 1], [0, 2]],
      [[1, 0], [1, 1], [1, 2]],
      [[2, 0], [2, 1], [2, 2]],
      [[0, 0], [1, 0], [2, 0]],
      [[0, 1], [1, 1], [2, 1]],
      [[0, 2], [1, 2], [2, 2]],
      [[0, 0], [1, 1], [2, 2]],
      [[0, 2], [1, 1], [2, 0]],
    ];

    for (const combo of winningCombinations) {
      const [a, b, c] = combo;
      if (this.gameBoard[a[0]][a[1]] === this.gameBoard[b[0]][b[1]] &&
          this.gameBoard[b[0]][b[1]] === this.gameBoard[c[0]][c[1]] &&
          this.gameBoard[a[0]][a[1]] !== ' ') {
        return;
      }
    }

    if (this.moves.length === 9) {
      return;
    }
  }

  public render(container: HTMLElement): void {
    container.innerHTML = '';

    const rowTemplate = (row: number) => {
      const rowEl = document.createElement('div');
      rowEl.className = 'row';
      for (let col = 0; col < 3; col++) {
        const cellEl = document.createElement('button');
        cellEl.className = 'cell';
        cellEl.textContent = this.gameBoard[row][col];
        cellEl.addEventListener('click', () => this.handleUserMove(row, col));
        rowEl.appendChild(cellEl);
      }
      return rowEl;
    };

    for (let row = 0; row < 3; row++) {
      const rowEl = rowTemplate(row);
      container.appendChild(rowEl);
    }

    const statusEl = document.createElement('div');
    statusEl.className = 'status';
    statusEl.textContent = `Current player: ${this.currentPlayer}`;
    container.appendChild(statusEl);
  }
}

