export class GameController {
  private currentPlayer: Player;
  private board: BoardState;
  private gameStatus: GameState;
  private gameHistory: Move[];

  constructor() {
    this.currentPlayer = Player.X;
    this.board = newBoard();
    this.gameStatus = GameState.InProgress;
    this.gameHistory = [];
  }

  public newGame(): void {
    this.currentPlayer = Player.X;
    this.board = newBoard();
    this.gameStatus = GameState.InProgress;
    this.gameHistory = [];
  }

  public handleMove(row: number, col: number): void {
    if (this.gameStatus !== GameState.InProgress || this.board.cells[row][col] !== BoardState.Empty) return;

    const move: Move = { row, col, player: this.currentPlayer };
    this.applyMove(move);

    this.currentPlayer = this.currentPlayer === Player.X ? Player.O : Player.X;
    this.gameHistory.push(move);
  }

  public currentPlayer(): Player { return this.currentPlayer; }

  public isGameOver(): boolean { return this.gameStatus !== GameState.InProgress; }

  public winnerOrNull(): Player | null {
    if (this.gameStatus === GameState.Draw) return null;
    return this.gameStatus === GameState.XWon ? Player.X : Player.O;
  }

  private applyMove(move: Move): void {
    const { row, col, player } = move;
    this.board.cells[row][col] = BoardState[player];
    this.gameStatus = getGameState(this.board.cells);

    if (this.gameStatus !== GameState.InProgress) {
      if (this.gameStatus === GameState.Draw) {
        console.log('The game is a draw!');
      } else {
        console.log(`Player ${player} wins!`);
      }
    }
  }
}

