export class Scene {
  private renderer: Renderer;
  private board: Array<Array<{ type: string; color: 'white' | 'black' }>>;

  constructor(private renderer: Renderer) {
    this.board = [];
  }

  setupBoard(): void {
    this.board = this.createBoard();
    this.renderBoard();
    this.placePieces();
  }

  addPiece(piece: { type: string; color: 'white' | 'black'; position: { x: number; y: number; z: number } }): void {
    this.renderer.scene.add(this.renderer.createPiece(piece));
  }

  updateGameState(newGameState: { turns: number; check?: boolean; checkmate?: boolean; stalemate?: boolean }): void {
    this.renderer.renderUI(newGameState);
  }

  private createBoard(): Array<Array<{ type: string; color: 'white' | 'black' }>> {
    const board: Array<Array<{ type: string; color: 'white' | 'black' }>> = [];
    for (let row = 0; row < 8; row++) {
      board[row] = [];
      for (let col = 0; col < 8; col++) {
        const color = (row + col) % 2 === 0 ? 'white' : 'black';
        board[row][col] = { type: 'empty', color };
      }
    }
    return board;
  }

  private renderBoard(): void {
    this.renderer.scene.add(this.renderer.createBoard());
  }

  private placePieces(): void {
    const whitePieces = [
      { type: 'rook', color: 'white' },
      { type: 'knight', color: 'white' },
      { type: 'bishop', color: 'white' },
      { type: 'queen', color: 'white' },
      { type: 'king', color: 'white' },
      { type: 'bishop', color: 'white' },
      { type: 'knight', color: 'white' },
      { type: 'rook', color: 'white' },
      { type: 'pawn', color: 'white' },
      { type: 'pawn', color: 'white' },
      { type: 'pawn', color: 'white' },
      { type: 'pawn', color: 'white' },
      { type: 'pawn', color: 'white' },
      { type: 'pawn', color: 'white' },
      { type: 'pawn', color: 'white' },
      { type: 'pawn', color: 'white' },
      { type: 'pawn', color: 'black' },
      { type: 'pawn', color: 'black' },
      { type: 'pawn', color: 'black' },
      { type: 'pawn', color: 'black' },
      { type: 'pawn', color: 'black' },
      { type: 'pawn', color: 'black' },
      { type: 'pawn', color: 'black' },
      { type: 'pawn', color: 'black' },
      { type: 'rook', color: 'black' },
      { type: 'knight', color: 'black' },
      { type: 'bishop', color: 'black' },
      { type: 'queen', color: 'black' },
      { type: 'king', color: 'black' },
      { type: 'bishop', color: 'black' },
      { type: 'knight', color: 'black' },
      { type: 'rook', color: 'black' },
    ];
    whitePieces.forEach((piece, index) => {
      const x = index % 8;
      const y = index < 8 ? 1 : 6;
      this.board[y][x] = { type: piece.type, color: piece.color };
    });
  }
}

import '../types/types.ts';
import { Renderer } from '../renderer/renderer.ts';
