export class Camera {
  private position: { x: number; y: number; z: number };
  private rotation: { x: number; y: number; z: number };
  private zoom: number;

  constructor() {
    this.position = { x: 0, y: 0, z: 5 };
    this.rotation = { x: 0, y: 0, z: 0 };
    this.zoom = 1;
  }

  orbitCamera(dx: number, dy: number): void {
    this.rotation.y += dx * 0.05;
    this.rotation.x -= dy * 0.05;
    this.rotation.x = Math.max(-20, Math.min(20, this.rotation.x));
  }

  panCamera(dx: number, dy: number): void {
    const speed = 0.1;
    this.position.x += dx * speed;
    this.position.z -= dy * speed;
  }

  zoomCamera(delta: number): void {
    this.zoom = Math.max(0.1, this.zoom + delta * 0.1);
  }

  getPosition(): { x: number; y: number; z: number } {
    return { x: this.position.x, y: this.position.y, z: this.position.z };
  }

  getRotation(): { x: number; y: number; z: number } {
    return { x: this.rotation.x, y: this.rotation.y, z: this.rotation.z };
  }

  getZoom(): number {
    return this.zoom;
  }
}

import '../types/types.ts';
import { Renderer } from '../renderer/renderer.ts';
import { Scene } from '../scene/scene.ts';
import { Camera } from '../camera/camera.ts';

export class InputHandler {
  private renderer: Renderer;
  private scene: Scene;
  private camera: Camera;
  private raycaster: THREE.Raycaster;
  private pointer: { x: number; y: number };

  constructor(renderer: Renderer, scene: Scene, camera: Camera) {
    this.renderer = renderer;
    this.scene = scene;
    this.camera = camera;
    this.raycaster = new THREE.Raycaster();
    this.pointer = { x: 0, y: 0 };
  }

  public handleKeydown(event: KeyboardEvent) {
    const key = event.key.toLowerCase();
    switch (key) {
      case 'w':
        this.sendMove(new THREE.Vector3(0, 1, 0));
        break;
      case 'a':
        this.sendMove(new THREE.Vector3(-1, 0, 0));
        break;
      case 's':
        this.sendMove(new THREE.Vector3(0, -1, 0));
        break;
      case 'd':
        this.sendMove(new THREE.Vector3(1, 0, 0));
        break;
      case 'q':
        this.sendMove(new THREE.Vector3(0, 0, -1));
        break;
      case 'e':
        this.sendMove(new THREE.Vector3(0, 0, 1));
        break;
      default:
        return;
    }
    event.preventDefault();
  }

  public handleMouse(event: MouseEvent) {
    this.pointer.x = (event.clientX / window.innerWidth) * 2 - 1;
    this.pointer.y = -(event.clientY / window.innerHeight) * 2 + 1;
    this.raycaster.setFromCamera(new THREE.Vector2(this.pointer.x, this.pointer.y), this.camera);
    const intersects = this.raycaster.intersectObjects(this.scene.board.children);
    if (intersects.length > 0) {
      const piece = intersects[0].object;
      if (piece.isPiece) {
        this.sendMove(piece.position);
      }
    }
  }

  private sendMove(position: THREE.Vector3) {
    try {
      const move = this.scene.board.getPieceAt(position);
      if (move) {
        this.scene.updateGameState(move);
      }
    } catch (error) {
      console.error('Failed to handle move:', error);
    }
  }
}

