export class Game {
  private scene: Scene;
  private renderer: Renderer;
  private inputHandler: InputHandler;
  private boardState: { [key: string]: { piece?: string; color: string; moved: boolean } };
  private currentPlayer: 'white' | 'black';
  private isAiTurn: boolean;
  private aiLevel: number;
  private moveHistory: { from: string; to: string }[];
  private selectedPiece: { piece: string; color: string; position: string };
  private gameover: 'checkmate' | 'stalemate' | null;

  constructor(scene: Scene, renderer: Renderer, inputHandler: InputHandler) {
    this.scene = scene;
    this.renderer = renderer;
    this.inputHandler = inputHandler;
    this.boardState = {
      a1: { piece: 'rook', color: 'white', moved: false },
      b1: { piece: 'knight', color: 'white', moved: false },
      c1: { piece: 'bishop', color: 'white', moved: false },
      d1: { piece: 'queen', color: 'white', moved: false },
      e1: { piece: 'king', color: 'white', moved: false },
      f1: { piece: 'bishop', color: 'white', moved: false },
      g1: { piece: 'knight', color: 'white', moved: false },
      h1: { piece: 'rook', color: 'white', moved: false },
      a2: { piece: 'pawn', color: 'white', moved: false },
      b2: { piece: 'pawn', color: 'white', moved: false },
      c2: { piece: 'pawn', color: 'white', moved: false },
      d2: { piece: 'pawn', color: 'white', moved: false },
      e2: { piece: 'pawn', color: 'white', moved: false },
      f2: { piece: 'pawn', color: 'white', moved: false },
      g2: { piece: 'pawn', color: 'white', moved: false },
      h2: { piece: 'pawn', color: 'white', moved: false },
      a8: { piece: 'rook', color: 'black', moved: false },
      b8: { piece: 'knight', color: 'black', moved: false },
      c8: { piece: 'bishop', color: 'black', moved: false },
      d8: { piece: 'queen', color: 'black', moved: false },
      e8: { piece: 'king', color: 'black', moved: false },
      f8: { piece: 'bishop', color: 'black', moved: false },
      g8: { piece: 'knight', color: 'black', moved: false },
      h8: { piece: 'rook', color: 'black', moved: false },
      a7: { piece: 'pawn', color: 'black', moved: false },
      b7: { piece: 'pawn', color: 'black', moved: false },
      c7: { piece: 'pawn', color: 'black', moved: false },
      d7: { piece: 'pawn', color: 'black', moved: false },
      e7: { piece: 'pawn', color: 'black', moved: false },
      f7: { piece: 'pawn', color: 'black', moved: false },
      g7: { piece: 'pawn', color: 'black', moved: false },
      h7: { piece: 'pawn', color: 'black', moved: false },
    };
    this.currentPlayer = 'white';
    this.isAiTurn = false;
    this.aiLevel = 1;
    this.moveHistory = [];
    this.selectedPiece = null;
    this.gameover = null;
  }

  public makeMove(from: string, to: string): void {
    if (!this.boardState[from] || !this.boardState[from].piece) return;
    const piece = this.boardState[from].piece;
    const color = this.boardState[from].color;
    const { x, y, z } = this.scene.board[from];
    this.boardState[to] = { piece, color, moved: false };
    this.boardState[from] = { piece: undefined, color: 'empty', moved: false };
    this.selectedPiece = null;
    this.moveHistory.push({ from, to });

    if (this.currentPlayer === 'white') {
      this.currentPlayer = 'black';
    } else {
      this.currentPlayer = 'white';
      this.handleAiTurn();
    }

    this.scene.updateGameState();
    this.scene.render();
  }

  public evaluateBoard(): number {
    let whiteScore = 0;
    let blackScore = 0;

    for (const key in this.boardState) {
      const { piece, color } = this.boardState[key];
      if (!piece) continue;

      if (color === 'white') {
        if (piece === 'pawn') whiteScore += 1;
        if (piece === 'knight') whiteScore += 3;
        if (piece === 'bishop') whiteScore += 3;
        if (piece === 'rook') whiteScore += 5;
        if (piece === 'queen') whiteScore += 9;
        if (piece === 'king') whiteScore += 100;
      } else {
        if (piece === 'pawn') blackScore += 1;
        if (piece === 'knight') blackScore += 3;
        if (piece === 'bishop') blackScore += 3;
        if (piece === 'rook') blackScore += 5;
        if (piece === 'queen') blackScore += 9;
        if (piece === 'king') blackScore += 100;
      }
    }

    return whiteScore - blackScore;
  }

  private handleAiTurn(): void {
    if (!this.isAiTurn) return;

    const move = this.findBestMove(this.aiLevel);
    this.makeMove(move.from, move.to);
  }

  private findBestMove(depth: number): { from: string; to: string } {
    const moves = this.getValidMoves(this.currentPlayer);
    if (moves.length === 0) return { from: '', to: '' };

    let bestMove: { from: string; to: string } = { from: '', to: '' };
    let bestScore = -Infinity;

    for (const { from, to } of moves) {
      this.makeMove(from, to);
      const score = this.evaluateBoard();
      this.makeMove(to, from);

      if (score > bestScore) {
        bestMove = { from, to };
        bestScore = score;
      }
    }

    return bestMove;
  }

  private getValidMoves(player: 'white' | 'black'): { from: string; to: string }[] {
    const validMoves: { from: string; to: string }[] = [];

    for (const key in this.boardState) {
      const { piece, color } = this.boardState[key];
      if (!piece || color !== player) continue;

      const moves = this.getPieceMoves(key, color);
      for (const move of moves) {
        const { from, to } = move;
        if (this.isMoveLegal(from, to, player)) {
          validMoves.push({ from, to });
        }
      }
    }

    return validMoves;
  }

  private getPieceMoves(position: string, color: 'white' | 'black'): { from: string; to: string }[] {
    const piece = this.boardState[position].piece;
    const moves: { from: string; to: string }[] = [];

    switch (piece) {
      case 'pawn':
        if (color === 'white') {
          if (this.boardState[position + '1']?.color === 'empty') {
            moves.push({ from: position, to: position + '1' });
            if (!this.boardState[position + '2']?.moved) {
              moves.push({ from: position, to: position + '2' });
            }
