export class AI {
  private aiLevel: number;

  constructor(aiLevel: number) {
    this.aiLevel = aiLevel;
  }

  makeMove(scene: Scene): void {
    const bestMove = this.findBestMove(scene);
    scene.updateGameState(bestMove.from, bestMove.to);
    scene.addPiece(bestMove.to);
  }

  evaluateBoard(scene: Scene): number {
    let score = 0;
    const whitePieces = scene.w_pieces;
    const blackPieces = scene.b_pieces;

    for (const piece of whitePieces) {
      const moves = this.getPieceMoves(piece);
      for (const move of moves) {
        if (this.isMoveLegal(move.from, move.to)) {
          score += 1;
        }
      }
    }

    for (const piece of blackPieces) {
      const moves = this.getPieceMoves(piece);
      for (const move of moves) {
        if (this.isMoveLegal(move.from, move.to)) {
          score -= 1;
        }
      }
    }

    return score;
  }

  findBestMove(scene: Scene): { from: string; to: string } {
    let bestMove: { from: string; to: string } = { from: 'a1', to: 'a2' };
    let bestScore = -Infinity;

    for (const move of this.getValidMoves(scene)) {
      const clone = this.cloneScene(scene);
      this.movePiece(clone, move.from, move.to);
      const score = this.minimax(clone, -Infinity, Infinity, false);
      if (score > bestScore) {
        bestScore = score;
        bestMove = move;
      }
    }

    return bestMove;
  }

  minimax(scene: Scene, alpha: number, beta: number, isMaximizingPlayer: boolean): number {
    if (scene.gameover) {
      return this.evaluateBoard(scene);
    }

    if (isMaximizingPlayer) {
      let bestScore = -Infinity;
      for (const move of this.getValidMoves(scene)) {
        const clone = this.cloneScene(scene);
        this.movePiece(clone, move.from, move.to);
        const score = this.minimax(clone, alpha, beta, false);
        bestScore = Math.max(score, bestScore);
        alpha = Math.max(alpha, score);
        if (beta <= alpha) break;
      }
      return bestScore;
    } else {
      let bestScore = Infinity;
      for (const move of this.getValidMoves(scene)) {
        const clone = this.cloneScene(scene);
        this.movePiece(clone, move.from, move.to);
        const score = this.minimax(clone, alpha, beta, true);
        bestScore = Math.min(score, bestScore);
        beta = Math.min(beta, score);
        if (beta <= alpha) break;
      }
      return bestScore;
    }
  }

  getValidMoves(scene: Scene): { from: string; to: string }[] {
    const validMoves: { from: string; to: string }[] = [];
    const pieces = scene.color === 'white' ? scene.w_pieces : scene.b_pieces;
    for (const piece of pieces) {
      const moves = this.getPieceMoves(piece);
      for (const move of moves) {
        if (this.isMoveLegal(move.from, move.to)) {
          validMoves.push(move);
        }
      }
    }
    return validMoves;
  }

  getPieceMoves(piece: string): { from: string; to: string }[] {
    let moves: { from: string; to: string }[] = [];
    const x = parseInt(piece.substring(0, 1));
    const y = parseInt(piece.substring(1));
    const color = piece[2] === 'w' ? 'white' : 'black';

    if (color === 'white') {
      if (y < 8) {
        moves.push({ from: piece, to: `${x}${y + 1}` });
        if (y === 1 && y + 2 < 8) {
          moves.push({ from: piece, to: `${x}${y + 2}` });
        }
      }
      if (x > 0 && y < 8) {
        moves.push({ from: piece, to: `${x - 1}${y + 1}` });
      }
      if (x < 7 && y < 8) {
        moves.push({ from: piece, to: `${x + 1}${y + 1}` });
      }
    } else {
      if (y > 0) {
        moves.push({ from: piece, to: `${x}${y - 1}` });
        if (y === 6 && y - 2 > 0) {
          moves.push({ from: piece, to: `${x}${y - 2}` });
        }
      }
      if (x > 0 && y > 0) {
        moves.push({ from: piece, to: `${x - 1}${y - 1}` });
      }
      if (x < 7 && y > 0) {
        moves.push({ from: piece, to: `${x + 1}${y - 1}` });
      }
    }

    return moves;
  }

  isMoveLegal(from: string, to: string): boolean {
    const x = parseInt(from[0]);
    const y = parseInt(from[1]);
    const toX = parseInt(to[0]);
    const toY = parseInt(to[1]);
    const dx = Math.abs(x - toX);
    const dy = Math.abs(y - toY);

    if (dx > 1 || dy > 1) return false;

    return true;
  }

  movePiece(scene: Scene, from: string, to: string): void {
    const x = parseInt(from[0]);
    const y = parseInt(from[1]);
    const toX = parseInt(to[0]);
    const toY = parseInt(to[1]);
    const piece = scene.board[y][x];
    scene.board[toY][toX] = piece;
    scene.board[y][x] = null;
  }

  cloneScene(scene: Scene): Scene {
    const newScene: Scene = {
      renderer: scene.renderer,
      board: scene.board.map(row => row.slice()),
      color: scene.color,
    };
    return newScene;
  }
}

