export class Clock {
  private start: number | null = null;
  private paused: boolean = false;
  private elapsed: number = 0;

  constructor() {}

  public start(): void {
    if (this.paused) {
      this.elapsed += Date.now() - this.start;
      this.paused = false;
    }
    if (!this.start) this.start = Date.now();
  }

  public stop(): void {
    if (!this.paused) {
      this.elapsed += Date.now() - this.start;
      this.paused = true;
      this.start = null;
    }
  }

  public reset(): void {
    this.elapsed = 0;
    this.start = null;
    this.paused = false;
  }

  public get elapsedMinutes(): number {
    return this.elapsed / 1000 / 60;
  }

  public get elapsedSeconds(): number {
    return this.elapsed / 1000;
  }
}

export function runMain() {
  const args = process.argv.slice(2);
  let command: 'add' | 'list' | 'complete' | 'delete' = 'list';
  let todoId: number | null = null;

  try {
    if (args.length > 0) {
      command = args[0] as any;
      if (args.length > 1) {
        todoId = parseInt(args[1], 10);
      }
    }

    const todos: { id: number; title: string; completed: boolean }[] = [];

    switch (command) {
      case 'add':
        if (todoId === null) {
          throw new Error('Missing todo title');
        }
        todos.push({ id: todos.length + 1, title: `Todo ${todos.length + 1}`, completed: false });
        break;
      case 'list':
        for (const todo of todos) {
          const mark = todo.completed ? '[X]' : '[ ]';
          console.log(`${mark} ${todo.title}`);
        }
        break;
      case 'complete':
        if (todoId === null) {
          throw new Error('Missing todo ID');
        }
        todos[todoId - 1] = { ...todos[todoId - 1], completed: true };
        break;
      case 'delete':
        if (todoId === null) {
          throw new Error('Missing todo ID');
        }
        todos.splice(todoId - 1, 1);
        break;
      default:
        throw new Error('Unknown command');
    }
  } catch (error) {
    console.error('Error:', error.message);
  }
}

export enum Priority { HIGH, MEDIUM, LOW };

export interface Task {
  id: number;
  title: string;
  isComplete: boolean;
  priority: Priority;
  dueDate?: Date;
}

export class TaskManager {
  private tasks: Task[] = [];

  public addTask(title: string, priority: Priority, dueDate?: Date): void {
    const newTask: Task = { id: this.tasks.length + 1, title, isComplete: false, priority, dueDate };
    this.tasks.push(newTask);
  }

  public listTasks(priority?: Priority): Task[] {
    if (priority) {
      return this.tasks.filter(t => t.priority === priority);
    }
    return this.tasks;
  }

  public completeTask(id: number): boolean {
    const task = this.tasks.find(t => t.id === id);
    if (!task) return false;
    task.isComplete = true;
    return true;
  }

  public deleteTask(id: number): boolean {
    const index = this.tasks.findIndex(t => t.id === id);
    if (index === -1) return false;
    this.tasks.splice(index, 1);
    return true;
  }
}

