export class TaskService {
  private tasks: { id: number; title: string; completed: boolean }[] = [];

  constructor() {
    try {
      const storedTasks = localStorage.getItem('tasks');
      if (storedTasks) {
        this.tasks = JSON.parse(storedTasks);
      }
    } catch (error) {
      console.error('Failed to load tasks:', error);
    }
  }

  public async listTasks(): Promise<{ id: number; title: string; completed: boolean }[]> {
    return this.tasks;
  }

  public async markComplete(taskId: number, isComplete: boolean): Promise<void> {
    const task = this.tasks.find(t => t.id === taskId);
    if (!task) {
      throw new Error('Task not found');
    }
    task.completed = isComplete;
    localStorage.setItem('tasks', JSON.stringify(this.tasks));
  }

  public async deleteTask(taskId: number): Promise<void> {
    this.tasks = this.tasks.filter(t => t.id !== taskId);
    localStorage.setItem('tasks', JSON.stringify(this.tasks));
  }
}

export function handleAdd(todo: string) {
  const todos = JSON.parse(localStorage.getItem('todos') || '[]');
  const newTodo = { id: Date.now(), text: todo, completed: false };
  todos.push(newTodo);
  localStorage.setItem('todos', JSON.stringify(todos));
  return `Added todo: ${newTodo.text}`;
}

export function handleListTodos(): string {
  const todos = JSON.parse(localStorage.getItem('todos') || '[]');
  if (todos.length === 0) {
    return 'No todos found.';
  }
  return todos.map(todo => `-${ todo.text }`).join('\n');
}

export function handleComplete(todoId: number) {
  const todos = JSON.parse(localStorage.getItem('todos') || '[]');
  const todo = todos.find(todo => todo.id === todoId);
  if (!todo) return 'Failed to complete todo.';
  todo.completed = true;
  localStorage.setItem('todos', JSON.stringify(todos));
  return `Completed todo: ${todo.text}`;
}

export function handleDelete(todoId: number) {
  const todos = JSON.parse(localStorage.getItem('todos') || '[]');
  const todo = todos.find(todo => todo.id === todoId);
  if (!todo) return 'Failed to delete todo.';
  const index = todos.indexOf(todo);
  todos.splice(index, 1);
  localStorage.setItem('todos', JSON.stringify(todos));
  return `Deleted todo: ${todo.text}`;
}

