export function render(container: HTMLElement) {
  container.className = 'task-list';

  const tasks = document.createElement('div');
  tasks.className = 'tasks';
  const tasksCount = document.createElement('div');
  tasksCount.className = 'tasks-count';
  tasksCount.textContent = 'Tasks: 0';
  tasks.appendChild(tasksCount);

  const buttons = document.createElement('div');
  buttons.className = 'buttons';
  const addTaskBtn = document.createElement('button');
  addTaskBtn.className = 'btn add-task';
  addTaskBtn.textContent = 'Add Task';
  addTaskBtn.addEventListener('click', () => {
    const taskInput = document.createElement('input');
    taskInput.type = 'text';
    taskInput.className = 'task-input';
    container.appendChild(taskInput);
    taskInput.focus();
    taskInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        const task = taskInput.value.trim();
        if (task) {
          addTask(task);
          taskInput.value = '';
          taskInput.remove();
        }
      }
    });
  });
  buttons.appendChild(addTaskBtn);

  const taskList = document.createElement('ul');
  taskList.className = 'task-list';
  buttons.appendChild(taskList);

  const completeTaskBtn = document.createElement('button');
  completeTaskBtn.className = 'btn complete-task';
  completeTaskBtn.textContent = 'Complete Task';
