    private tasksContainer: HTMLElement;

    constructor(container: HTMLElement) {
      this.container = container;
      this.taskService = new TaskService();
      this.render();
    }

    private render() {
      this.container.innerHTML = `
        <div class="row">
          <div class="col">
            <label for="searchInput" class="label">Title:</label>
            <input id="searchInput" type="text" oninput="filterTasks(event)">
