export interface Task {
  id: number;
  title: string;
  description?: string;
  priority: number;
  dueDate?: Date | null;
  isComplete: boolean;
}

export class TaskService {
  private tasks: Task[] = [];
  private nextId = 1;

  public addTask(task: Task): void {
    if (this.validateTask(task)) {
      const newTask = { ...task, id: this.nextId++ };
      this.tasks.push(newTask);
    } else {
      throw new Error('Invalid task provided');
    }
  }

  public listTasks(): Task[] {
    return [...this.tasks];
  }

  public completeTask(id: number): boolean {
    const index = this.tasks.findIndex(task => task.id === id);
    if (index !== -1) {
      this.tasks[index].isComplete = true;
      return true;
    }
    return false;
  }

  public deleteTask(id: number): void {
    this.tasks = this.tasks.filter(task => task.id !== id);
  }

  private validateTask(task: Task): boolean {
    if (!task.title || !task.priority) {
      return false;
    }
    if (typeof task.dueDate === 'string' && task.dueDate) {
      const date = new Date(task.dueDate);
      if (!isNaN(date.getTime())) {
        return true;
      }
    }
    return false;
  }
}

export class GameService {
  private board: string[] = Array(9).map(() => '');
  private currentPlayer: 'X' | 'O' = 'X';
  private winner: 'X' | 'O' | null = null;

  public getBoard(): string[] { return this.board; }
  public getCurrentPlayer(): 'X' | 'O' { return this.currentPlayer; }
  public getWinner(): 'X' | 'O' | null { return this.winner; }

  public handleMove(index: number): void {
    if (this.board[index] !== '' || this.winner !== null) return;
    this.board[index] = this.currentPlayer;
    this.currentPlayer = this.currentPlayer === 'X' ? 'O' : 'X';
    const winningCombinations = [[0, 1, 2], [3, 4, 5], [6, 7, 8], [0, 3, 6], [1, 4, 7], [2, 5, 8], [0, 4, 8], [2, 4, 6]];
    for (const combo of winningCombinations) {
      if (this.board[combo[0]] === this.board[combo[1]] && this.board[combo[1]] === this.board[combo[2]] && this.board[combo[0]] !== '') { this.winner = this.board[combo[0]]; return; }
    }
    if (this.board.every((cell) => cell !== '')) this.winner = null;
  }
}

export class GameClient {
  private board: HTMLDivElement;
  private currentPlayer: HTMLParagraphElement;
  private winner: HTMLParagraphElement;
  private game: GameService;

  constructor(board: HTMLDivElement, currentPlayer: HTMLParagraphElement, winner: HTMLParagraphElement) {
    this.board = board;
    this.currentPlayer = currentPlayer;
    this.winner = winner;
    this.game = new GameService();
  }

  public start(): void {
    const cells = Array.from(this.board.children).map((cell) => cell as HTMLDivElement);
    cells.forEach((cell) => {
      cell.addEventListener('click', (e) => this.handleMove(cells.indexOf(cell as HTMLDivElement)));
    });
    this.updateDisplay();
  }

  public handleMove(index: number): void {
    this.game.handleMove(index);
    this.updateDisplay();
  }

  private updateDisplay(): void {
    const board = this.game.getBoard();
    const currentPlayer = this.game.getCurrentPlayer();
    const winner = this.game.getWinner();
    Array.from(this.board.children).forEach((cell, i) => {
      cell.textContent = board[i];
    });
    this.currentPlayer.textContent = `Current Player: ${currentPlayer}`;
    if (winner) this.winner.textContent = `Winner: ${winner}`;
  }
}

export class Game {
    private board: string[] = Array(9).fill(null);
    private currentPlayer: 'X' | 'O' = 'X';
    private winner: 'X' | 'O' | null = null;
    private isGameOverValue: boolean = false;

    constructor() {}

    placeMark(index: number): void {
        if (this.board[index] === null && !this.isGameOverValue) {
            this.board[index] = this.currentPlayer;
            this.checkWin();
            this.nextPlayer();
        } else {
            throw new Error('Cell already occupied or game over');
        }
    }

    checkWin(): void {
        const winningCombinations = [
            [0, 1, 2], [3, 4, 5], [6, 7, 8],
            [0, 3, 6], [1, 4, 7], [2, 5, 8],
            [0, 4, 8], [2, 4, 6]
        ];

        for (const combination of winningCombinations) {
            const [a, b, c] = combination;
            if (this.board[a] && this.board[a] === this.board[b] && this.board[a] === this.board[c]) {
                this.winner = this.board[a] as 'X' | 'O';
                this.isGameOverValue = true;
                return;
            }
        }

        if (!this.board.includes(null)) {
            this.isGameOverValue = true;
        }
    }

    hasEmptySpaces(): boolean {
        return this.board.filter(cell => cell === null).length > 0;
    }

    nextPlayer(): void {
        this.currentPlayer = this.currentPlayer === 'X' ? 'O' : 'X';
    }

    getBoardState(): string[] {
        return this.board;
    }

    getWinner(): 'X' | 'O' | null {
        return this.winner;
    }

    isGameOver(): boolean {
        return this.isGameOverValue;
    }
}

