export function handleMarkerPlacement(cell: number) {
  const cells = document.querySelectorAll('.cell');
  if (cell === -1) {
    cells.forEach((c) => c.textContent = '');
    return;
  }
  const currentPlayer = 'X';
  const cellsArray = Array.from(cells);
  if (cellsArray[cell].textContent) return;
  cellsArray[cell].textContent = currentPlayer;
  cellsArray.forEach((c, i) => {
    if (c.textContent) {
      const display = document.querySelector('.display') as HTMLDivElement;
      display.textContent = `${currentPlayer}: ${i + 1}`;
    }
  });
}

