export function parseArgs(args: string[]): CommandLineArgs {
  if (args.length < 2) {
    throw new Error('Missing command argument');
  }

  const command = args[1] as 'add' | 'list' | 'complete' | 'delete';
  const taskArg = args.slice(2).join(' ');

  let task: Task | undefined = undefined;

  if (command === 'add') {
    task = parseTask(taskArg);
  }

  return { command, task };
}

export function parseTask(taskStr: string): Task {
  const [title] = taskStr.split(':');
  return { id: 0, title, status: TaskStatus.Pending, createdAt: new Date().toISOString() };
}

