    try {
      const tasks = this.taskHandler.listTasks();
      this.renderTasks(tasks);
    } catch (error) {
      this.handleError(error as Error);
    }
  }

  public completeTask(id: number): void {
    try {
      this.taskHandler.completeTask(id);
      const tasks = this.taskHandler.listTasks();
      this.renderTasks(tasks);
    } catch (error) {
      this.handleError(error as Error);
    }
  }

