export class Renderer {
  private canvas: HTMLCanvasElement;
  private context: CanvasRenderingContext2D;
  private board: { [key: string]: { x: number; y: number; width: number; height: number; color: string }[] };
  private pieces: { [key: string]: { x: number; y: number; width: number; height: number; color: string }[] };
  private camera: { rotation: number; position: { x: number; y: number; z: number } };
  private state: { currentPlayer: Player; moves: Move[] };

  constructor(canvas: HTMLCanvasElement, board: { [key: string]: { x: number; y: number; width: number; height: number; color: string }[] }, pieces: { [key: string]: { x: number; y: number; width: number; height: number; color: string }[] }, camera: { rotation: number; position: { x: number; y: number; z: number } }, state: { currentPlayer: Player; moves: Move[] }) {
    this.canvas = canvas;
    this.context = canvas.getContext('2d')!;
    this.board = board;
    this.pieces = pieces;
    this.camera = camera;
    this.state = state;
  }

  public update() {
    this.context.clearRect(0, 0, this.canvas.width, this.canvas.height);
    this.renderBoard();
    this.renderPieces();
    this.renderCamera();
  }

  private renderBoard() {
    const boardColors = ['#f0f0f0', '#e0e0e0'];
    for (let i = 0; i < 8; i++) {
      for (let j = 0; j < 8; j++) {
        const color = (i + j) % 2 === 0 ? boardColors[0] : boardColors[1];
        this.context.fillStyle = color;
        this.context.fillRect(i * 100, j * 100, 100, 100);
      }
    }
  }

  private renderPieces() {
    for (const piece of this.pieces[this.state.currentPlayer]) {
      this.context.fillStyle = piece.color;
      this.context.fillRect(piece.x, piece.y, piece.width, piece.height);
    }
  }

  private renderCamera() {
    this.context.strokeStyle = 'black';
    this.context.strokeRect(this.camera.position.x - 50, this.camera.position.y - 50, 100, 100);
  }

  public handleCameraRotation(rotation: number) {
    this.camera.rotation = rotation;
    this.update();
  }

  public handlePieceMove(from: number, to: number) {
    const move = new Move(from, to);
    this.state.moves.push(move);
    this.state.currentPlayer = this.state.currentPlayer === Player.White ? Player.Black : Player.White;
    this.update();
  }
}

export function createRenderer(canvas: HTMLCanvasElement, board: { [key: string]: { x: number; y: number; width: number; height: number; color: string }[] }, pieces: { [key: string]: { x: number; y: number; width: number; height: number; color: string }[] }, camera: { rotation: number; position: { x: number; y: number; z: number } }, state: { currentPlayer: Player; moves: Move[] }): Renderer {
  return new Renderer(canvas, board, pieces, camera, state);
}

