export interface Move {
  from: number;
  to: number;
}

export enum Player {
  White = 'W',
  Black = 'B',
}

export interface BoardState {
  currentPlayer: Player;
  moves: Move[];
  board: string[];
  piecePositions: { [key: string]: { x: number; y: number } };
}

export function isMoveValid(move: Move, state: BoardState): boolean {
  const { currentPlayer, moves, board, piecePositions } = state;
  const [from, to] = move;
  const piece = board[from];
  if (!piece || piece === currentPlayer) return false;
  const dx = Math.abs(from - to);
  const dy = Math.abs(from - to);
  if (dx !== dy) return false;
  const xDir = from < to ? 1 : -1;
  const yDir = from < to ? 1 : -1;
  let x = from + xDir;
  let y = from + yDir;
  while (x !== to && y !== to) {
    if (board[x] !== '') return false;
    x += xDir;
    y += yDir;
  }
  return true;
}

export function makeMove(move: Move, state: BoardState): BoardState {
  const { currentPlayer, moves, board, piecePositions } = state;
  if (!isMoveValid(move, state)) return state;
  const [from, to] = move;
  const piece = board[from];
  board[from] = '';
  board[to] = piece;
  piecePositions[piece] = { x: to % 8, y: Math.floor(to / 8) };
  moves.push(move);
  return { currentPlayer: currentPlayer === Player.White ? Player.Black : Player.White, moves, board, piecePositions };
}

