export function initializeGame(): GameState {
  const board: { [x: number]: { color: 'white' | 'black'; piece: 'cheese' | 'pawn' | undefined } } = {};
  for (let x = 0; x < 8; x++) {
    for (let y = 0; y < 8; y++) {
      board[x] = { color: 'white', piece: undefined };
    }
  }
  return { turn: 'player', board, score: { player: 0, ai: 0 } };
