export function handleInput(state: GameState, input: { type: 'click' | 'key'; data: { x: number; y: number } }) {
  if (state.turn !== 'player') return;
  const { x, y } = input.data;
  if (x < 0 || x >= 8 || y < 0 || y >= 8) return;

  const piece = state.board[x][y].piece;
  if (!piece) return;

  state.board[x][y].piece = undefined;
  state.board[input.data.x][input.data.y].piece = piece;
  state.turn = 'ai';
}

