export class GameLogic {
  private currentPlayer: Player;
  private board: { [key: string]: number };
  private moves: Move[];

  constructor() {
    this.currentPlayer = Player.White;
    this.board = {};
    this.moves = [];
  }

  public makeMove(from: number, to: number): void {
    if (this.board[from] === undefined) {
      throw new Error('Invalid move: no piece at the starting position');
    }

    this.moves.push(new Move(from, to));
    this.board[to] = this.board[from];
    delete this.board[from];
    this.currentPlayer = this.currentPlayer === Player.White ? Player.Black : Player.White;
  }

  public getGameState(): BoardState {
    return {
      currentPlayer: this.currentPlayer,
      moves: this.moves,
      board: Object.keys(this.board).map((key) => parseInt(key)),
    };
  }

  public checkGameState(): string {
    const winningPositions = [[0, 1, 2], [3, 4, 5], [6, 7, 8], [0, 3, 6], [1, 4, 7], [2, 5, 8], [0, 4, 8], [2, 4, 6]];

    for (const position of winningPositions) {
      const [a, b, c] = position;
      if (this.board[a] !== undefined && this.board[a] === this.board[b] && this.board[a] === this.board[c]) {
        return this.board[a] === Player.White ? 'White wins' : 'Black wins';
      }
    }

    if (Object.keys(this.board).length === 9) {
      return 'Draw';
    }

    return 'Game in progress';
  }
}

