  }
}

function miniMax(boardSize: number, player: Player): { from: number; to: number; value: number }[] {
  const board: string[][] = Array.from({ length: boardSize }, () => Array(boardSize).fill(''));
  const moves: { from: number; to: number; value: number }[] = [];

  for (let i = 0; i < boardSize; i++) {
    for (let j = 0; j < boardSize; j++) {
      if (board[i][j] === '') {
        const newBoard = cloneBoard(board);
        const to = makeMove(newBoard, i, j, player);
        const value = miniMax(boardSize, player === Player.White ? Player.Black : Player.White)[0].value;
        moves.push({ from: i * boardSize + j, to: to, value });
      }
    }
  }

  return moves;
}

function checkWinner(board: string[][]): Player | null {
  for (let i = 0; i < 3; i++) {
    if (board[i][0] !== '' && board[i][0] === board[i][1] && board[i][1] === board[i][2]) return board[i][0];
    if (board[0][i] !== '' && board[0][i] === board[1][i] && board[1][i] === board[2][i]) return board[0][i];
  }
  if (board[0][0] !== '' && board[0][0] === board[1][1] && board[1][1] === board[2][2]) return board[0][0];
  if (board[0][2] !== '' && board[0][2] === board[1][1] && board[1][1] === board[2][0]) return board[0][2];
  return null;
}

function makeMove(board: string[][], from: number, to: number, player: Player): number {
  const x = Math.floor(from / 3);
  const y = from % 3;
  const newX = Math.floor(to / 3);
  const newY = to % 3;
  board[newX][newY] = player;
  board[x][y] = '';
  return to;
}

function cloneBoard(board: string[][]): string[][] {
  return board.map(row => row.slice());
}

/**
 * Core engine of a chess game application.
 */
class ChessEngine {
  public state: Record<string, string> = {};

  /**
   * Adds a new move to the game state.
   * @param move The moveset string.
   */
  addMove(move: string) {
    this.state['last_move'] = move;
  }

  /**
   * Updates the current board position based on an engine's move suggestion.
   * @param suggestedMove The suggested move from the engine.
   */
  updateBoard(suggestedMove: string) {
    this.state['current_board_position'] = suggestedMove;
  }

  /**
   * Computes a checkmate for the given position.
   * @returns true if a checkmate is detected, false otherwise.
   */
  detectCheckmate() {
    // Basic logic to detect king check
    const hasKing = (position: string): boolean => {
      const pieces = new Set(['bR', 'nB']);
      for (const piece of pieces) {
        if (piece === position[0]) {
          return true;
        }
      }
      return false;
    };

    const kings: { row: number; col: number }[] = [];
    Object.entries(this.state).forEach(([key, value]) => {
      if (value === 'k') kings.push({ row: parseInt(key.charAt(1), 6), col: key.charCodeAt(0) - 'a'.charCodeAt(0) + 1 });
    });

    for (const king of kings) {
      for (let dx = -1; dx <= 1; dx++) {
        for (let dy = -1; dy <= 1; dy++) {
          const newKingRow = king.row + dx;
          const newKingCol = king.col + dy;

          if (!isNaN(newKingRow) && !isNaN(newKingCol)) {
            const newLocation = `${String.fromCharCode('a'.charCodeAt(0) + newKingCol)}${newKingRow}`;
            if (this.state.hasOwnProperty(newLocation) && this.state[newLocation] !== 'k') return true;
          }
        }
      }
    }

    return false;
  }
}

